using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Events;using UnityEditor.SceneManagement;using TMPro;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class AuthorHud06A{
static RectTransform Node(string name,Transform parent){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.sizeDelta=new Vector2(200,40);return r;}
static void Fill(RectTransform r,float inset=0){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=new Vector2(inset,inset);r.offsetMax=new Vector2(-inset,-inset);}
static TMP_Text Label(string name,Transform parent,TMP_Text style){var t=Node(name,parent).gameObject.AddComponent<TextMeshProUGUI>();t.font=style.font;t.fontSharedMaterial=style.fontSharedMaterial;t.fontSize=18;t.enableAutoSizing=false;t.color=new Color(.84f,.9f,.89f);t.raycastTarget=false;t.textWrappingMode=TextWrappingModes.Normal;return t;}
static UnityEngine.UI.Button Button(string name,Transform parent,string caption,RailwayOverview view,UnityEngine.UI.Button style,string command){var r=Node(name,parent);var im=r.gameObject.AddComponent<UnityEngine.UI.Image>();im.sprite=((UnityEngine.UI.Image)style.targetGraphic).sprite;im.type=UnityEngine.UI.Image.Type.Sliced;var b=r.gameObject.AddComponent<UnityEngine.UI.Button>();b.targetGraphic=im;b.colors=style.colors;var t=Label("Caption",r,view.Railway.Title);Fill(t.rectTransform,6);t.text=caption;t.overflowMode=TextOverflowModes.Ellipsis;t.alignment=TextAlignmentOptions.MidlineLeft;if(command!=null)UnityEventTools.AddStringPersistentListener(b.onClick,view.Execute,command);return b;}
public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();var report=new JArray();try{foreach(var sceneName in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+sceneName+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var rail=h.Sandbox.RailwayHud;if(rail.GetComponent<RailwayOverview>()!=null)throw new Exception("Already authored");var v=rail.gameObject.AddComponent<RailwayOverview>();v.Hud=h;v.Railway=rail;v.Legacy=rail.Panel.GetComponent<CanvasGroup>();if(v.Legacy==null)v.Legacy=rail.Panel.AddComponent<CanvasGroup>();v.Root=Node("RailwayOverview",rail.transform.parent);v.Root.sizeDelta=new Vector2(1060,600);v.Root.anchoredPosition=new Vector2(336,-184);var bg=v.Root.gameObject.AddComponent<UnityEngine.UI.Image>();bg.sprite=rail.Panel.GetComponent<UnityEngine.UI.Image>().sprite;bg.type=UnityEngine.UI.Image.Type.Sliced;var style=rail.Commands.First(c=>c.Command=="start").Button;v.Heading=Label("Heading",v.Root,rail.Title);v.List=Node("RouteList",v.Root);v.Detail=Node("OperationDetail",v.Root);v.Page=Label("Page",v.List,rail.Title);v.Empty=Label("Empty",v.List,rail.Title);v.Rows=new UnityEngine.UI.Button[4];for(int i=0;i<4;i++){v.Rows[i]=Button("Route"+i,v.List,"노선",v,style,null);UnityEventTools.AddIntPersistentListener(v.Rows[i].onClick,v.SelectRow,i);}v.Previous=Button("Previous",v.List,"이전",v,style,"page-prev");v.Next=Button("Next",v.List,"다음",v,style,"page-next");v.Back=Button("Back",v.Root,"목록",v,style,"list");v.Close=Button("Close",v.Root,"닫기",v,style,"close");
var actions=new System.Collections.Generic.List<RailwayOverview.Action>();foreach(var p in new[]{("new","새 노선"),("connect","역 연결"),("start","운행 시작"),("stop","중지 요청"),("fuel","석탄 보급"),("cargo","화물·역 상세"),("defense","방어칸"),("edit","노선 편집"),("cancel-pending","예약 취소")})actions.Add(new RailwayOverview.Action{Command=p.Item1,Button=Button(p.Item1,p.Item1 is "new" or "connect"?v.List:v.Detail,p.Item2,v,style,p.Item1)});v.Actions=actions.ToArray();
v.DetailScroll=Node("SummaryScroll",v.Detail);var scroll=v.DetailScroll.gameObject.AddComponent<UnityEngine.UI.ScrollRect>();scroll.horizontal=false;scroll.vertical=true;scroll.movementType=UnityEngine.UI.ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=28;var viewport=Node("Viewport",v.DetailScroll);Fill(viewport);var image=viewport.gameObject.AddComponent<UnityEngine.UI.Image>();image.color=new Color(.04f,.09f,.1f,.8f);viewport.gameObject.AddComponent<UnityEngine.UI.Mask>().showMaskGraphic=true;scroll.viewport=viewport;var content=Node("Content",viewport);content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.sizeDelta=Vector2.zero;scroll.content=content;var layout=content.gameObject.AddComponent<UnityEngine.UI.VerticalLayoutGroup>();layout.padding=new RectOffset(10,10,8,8);layout.childControlWidth=layout.childControlHeight=true;layout.childForceExpandHeight=false;content.gameObject.AddComponent<UnityEngine.UI.ContentSizeFitter>().verticalFit=UnityEngine.UI.ContentSizeFitter.FitMode.PreferredSize;v.DetailText=Label("OperationSummary",content,rail.Title);
v.LegacyBack=Button("OverviewReturn",rail.Panel.transform,"운행 화면으로",v,style,"overview");var back=(RectTransform)v.LegacyBack.transform;back.anchoredPosition=new Vector2(0,-578);back.sizeDelta=new Vector2(220,40);v.LegacyBack.gameObject.SetActive(false);v.Root.gameObject.SetActive(false);EditorUtility.SetDirty(v);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");report.Add(new JObject{{"scene",sceneName},{"savedRows",4},{"savedActions",v.Actions.Length},{"legacyPreserved",true}});}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}File.WriteAllText("Docs/Measurements/2026-10-02-hud-06a/author.json",report.ToString());return report.ToString();}}
